import { isOriginId } from './story';
import type { OriginTimes, Station, StepFreeDataset } from './types';

// Generated by poster/analysis/analyse.py.
const STEP_FREE_DATA_URL = '/data/step-free.json';

let datasetRequest: Promise<unknown> | null = null;

export async function loadStepFreeDataset() {
    if (typeof window === 'undefined') return null;

    if (!datasetRequest) {
        datasetRequest = (async () => {
            try {
                const response = await fetch(STEP_FREE_DATA_URL, {
                    headers: {
                        accept: 'application/json'
                    }
                });
                if (!response.ok) return null;
                return (await response.json()) as unknown;
            } catch {
                return null;
            }
        })();
    }

    const dataset = parseStepFreeDataset(await datasetRequest);
    if (dataset === null) {
        // Failed reads should not poison cache forever.
        datasetRequest = null;
    }
    return dataset;
}

export function parseStepFreeDataset(payload: unknown): StepFreeDataset | null {
    // Runtime validation: the dataset is untrusted input, so reject anything malformed outright
    // instead of rendering a partially wrong map.
    if (typeof payload !== 'object' || payload === null) return null;
    const candidate = payload as Partial<Record<keyof StepFreeDataset, unknown>>;
    if (
        typeof candidate.departure !== 'string' ||
        !isPositiveNumber(candidate.reachThresholdMin) ||
        !Array.isArray(candidate.stations) ||
        !Array.isArray(candidate.origins)
    ) {
        return null;
    }

    const stations: Station[] = [];
    for (const item of candidate.stations) {
        const station = parseStation(item);
        if (!station) return null;
        stations.push(station);
    }

    const origins: OriginTimes[] = [];
    for (const item of candidate.origins) {
        const origin = parseOriginTimes(item, stations.length);
        if (!origin) return null;
        origins.push(origin);
    }

    return {
        departure: candidate.departure,
        reachThresholdMin: candidate.reachThresholdMin,
        stations,
        origins
    };
}

function parseStation(item: unknown): Station | null {
    if (typeof item !== 'object' || item === null) return null;
    const station = item as Partial<Record<keyof Station, unknown>>;
    if (
        typeof station.id !== 'string' ||
        typeof station.name !== 'string' ||
        !Number.isFinite(station.lon) ||
        !Number.isFinite(station.lat)
    ) {
        return null;
    }
    return {
        id: station.id,
        name: station.name,
        lon: station.lon as number,
        lat: station.lat as number
    };
}

function parseOriginTimes(item: unknown, stationCount: number): OriginTimes | null {
    if (typeof item !== 'object' || item === null) return null;
    const origin = item as Partial<Record<keyof OriginTimes, unknown>>;
    if (
        !isOriginId(origin.id) ||
        typeof origin.name !== 'string' ||
        !Number.isInteger(origin.stationIndex) ||
        (origin.stationIndex as number) < 0 ||
        (origin.stationIndex as number) >= stationCount
    ) {
        return null;
    }
    const any = parseMinutes(origin.any, stationCount);
    const stepFree = parseMinutes(origin.stepFree, stationCount);
    if (!any || !stepFree) return null;

    return {
        id: origin.id,
        name: origin.name,
        stationIndex: origin.stationIndex as number,
        any,
        stepFree
    };
}

function parseMinutes(values: unknown, stationCount: number): Array<number | null> | null {
    // Arrays must line up one-to-one with the station list.
    if (!Array.isArray(values) || values.length !== stationCount) return null;
    const minutes: Array<number | null> = [];
    for (const value of values) {
        if (value === null) {
            minutes.push(null);
        } else if (typeof value === 'number' && Number.isFinite(value) && value >= 0) {
            minutes.push(value);
        } else {
            return null;
        }
    }
    return minutes;
}

function isPositiveNumber(value: unknown): value is number {
    return typeof value === 'number' && Number.isFinite(value) && value > 0;
}

export function countWithin(minutes: Array<number | null>, thresholdMin: number) {
    return minutes.filter((value) => value !== null && value <= thresholdMin).length;
}
